const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. PHARMACY TENANT (الصيدليات المشتركة بنظام الـ White-Label)\n// ----------------------------------------------------\nmodel Pharmacy {\n  id                   String   @id @default(cuid())\n  slug                 String   @unique // e.g. \"dr-ramon-tanta\", \"al-amal-cairo\"\n  nameAr               String // اسم الصيدلية بالعربي\n  nameEn               String // اسم الصيدلية بالإنجليزي\n  licenseNumber        String? // رقم ترخيص وزارة الصحة\n  ownerName            String // اسم الصيدلي المدير المسؤول\n  phone                String // هاتف الصيدلية الأساسي\n  whatsapp             String // رقم الواتساب المباشر لخدمة التوصيل\n  email                String?\n  address              String // العنوان التفصيلي\n  city                 String // المدينة / المركز (طنطا، المنصورة، مدينة نصر...)\n  governorate          String // المحافظة (الغربية، القاهرة، الدقهلية...)\n  lat                  Float? // إحداثيات GPS لتحديد الأقرب للعميل\n  lng                  Float?\n  logoUrl              String? // لوجو الصيدلية\n  coverUrl             String? // غلاف صفحة الصيدلية\n  rating               Float    @default(4.9)\n  isOpen               Boolean  @default(true)\n  deliveryAvailable    Boolean  @default(true)\n  deliveryFee          Float    @default(15.0)\n  deliveryTimeEstimate String   @default(\"25 - 40 دقيقة\")\n  workingHours         String   @default(\"24 ساعة / خدمة ليلية\")\n  isVerified           Boolean  @default(true)\n  subscriptionPlan     String   @default(\"PRO\") // FREE, PRO, ENTERPRISE\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n\n  staff         PharmacyStaff[]\n  inventory     PharmacyInventory[]\n  couriers      Courier[]\n  orders        Order[]\n  prescriptions Prescription[]\n}\n\n// ----------------------------------------------------\n// 2. PHARMACY STAFF & ROLES (فريق عمل الصيدلية)\n// ----------------------------------------------------\nmodel PharmacyStaff {\n  id         String   @id @default(cuid())\n  pharmacyId String\n  pharmacy   Pharmacy @relation(fields: [pharmacyId], references: [id], onDelete: Cascade)\n  name       String\n  username   String   @unique\n  password   String\n  role       String   @default(\"pharmacist\") // manager, pharmacist, cashier\n  phone      String?\n  isActive   Boolean  @default(true)\n  createdAt  DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 3. COURIER FLEET (طيارين ودليفري الصيدلية)\n// ----------------------------------------------------\nmodel Courier {\n  id          String   @id @default(cuid())\n  pharmacyId  String\n  pharmacy    Pharmacy @relation(fields: [pharmacyId], references: [id], onDelete: Cascade)\n  name        String\n  phone       String\n  vehicleType String   @default(\"motorcycle\") // motorcycle, bike, car\n  isAvailable Boolean  @default(true)\n  currentLat  Float?\n  currentLng  Float?\n  totalOrders Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 4. CUSTOMER / PATIENT (العملاء والمرضى)\n// ----------------------------------------------------\nmodel Customer {\n  id              String    @id @default(cuid())\n  name            String\n  phone           String\n  email           String?\n  city            String?\n  address         String?\n  lat             Float?\n  lng             Float?\n  allergies       String? // الحساسية الدوائية (بنسلين، سلفا، إلخ)\n  chronicDiseases String? // أمراض مزمنة (ضغط، سكر، غدة...)\n  otpCode         String?\n  otpExpires      DateTime?\n  isVerified      Boolean   @default(false)\n  whatsappActive  Boolean   @default(false)\n  totalOrders     Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @default(now()) @updatedAt\n\n  orders           Order[]\n  prescriptions    Prescription[]\n  labReports       LabReport[]\n  shortageRequests ShortageRequest[]\n}\n\n// ----------------------------------------------------\n// 5. MASTER EGYPTIAN DRUG CATALOG (دليل الدواء المصري الشامل)\n// ----------------------------------------------------\nmodel Medicine {\n  id                   String   @id @default(cuid())\n  tradeNameAr          String // الاسم التجاري بالعربي (مثلاً: أوجمنتين 1 جم)\n  tradeNameEn          String // Trade Name (e.g. Augmentin 1g)\n  genericName          String // المادة الفعالة (Amoxicillin + Clavulanic Acid)\n  strength             String? // التركيز (1000 mg, 500 mg)\n  dosageForm           String // الشكل الدوائي (أقراص، شراب، حقن، فوار، كريم)\n  category             String // التصنيف الطبي (مضاد حيوي، مسكن، أدوية ضغط، سكر، تجميل)\n  officialPrice        Float // السعر الجبري المعتمد من هيئة الدواء (ج.م)\n  manufacturer         String? // الشركة المصنعة (GSK, Eva, Amoun, Pfizer...)\n  barcode              String?\n  image                String? // صورة العبوة\n  requiresPrescription Boolean  @default(false) // هل يحتاج روشتة رسمية\n  isShortage           Boolean  @default(false) // يعاني من شح ونواقص في السوق\n  alternatives         String? // أسماء البدائل والمثائل (JSON string or comma-separated)\n  description          String? // دواعي الاستعمال وموانع المحاذير\n  createdAt            DateTime @default(now())\n\n  inventory PharmacyInventory[]\n}\n\n// ----------------------------------------------------\n// 6. PHARMACY INVENTORY (مخزون كل صيدلية)\n// ----------------------------------------------------\nmodel PharmacyInventory {\n  id            String   @id @default(cuid())\n  pharmacyId    String\n  pharmacy      Pharmacy @relation(fields: [pharmacyId], references: [id], onDelete: Cascade)\n  medicineId    String\n  medicine      Medicine @relation(fields: [medicineId], references: [id], onDelete: Cascade)\n  stockQuantity Int      @default(0)\n  price         Float // السعر المعروض\n  isAvailable   Boolean  @default(true)\n  expiryDate    String? // تاريخ الصلاحية\n  updatedAt     DateTime @updatedAt\n\n  @@unique([pharmacyId, medicineId])\n}\n\n// ----------------------------------------------------\n// 7. AI PRESCRIPTION SCAN (قراءة وفحص الروشتات بـ Gemini Multimodal)\n// ----------------------------------------------------\nmodel Prescription {\n  id              String    @id @default(cuid())\n  customerId      String?\n  customer        Customer? @relation(fields: [customerId], references: [id])\n  pharmacyId      String?\n  pharmacy        Pharmacy? @relation(fields: [pharmacyId], references: [id])\n  imageUrl        String // صورة الروشتة المرفوعة\n  rawOcrText      String? // النص المستخرج بالكامل\n  parsedMedicines String // JSON: [{ tradeName, dosage, frequency, duration, isAvailable, alternative }]\n  doctorSpecialty String? // تخصص الطبيب (باطنة، عظام، أطفال...)\n  aiConfidence    Float     @default(0.95)\n  status          String    @default(\"SCANNED\") // SCANNED, REVIEWED, QUOTED, ORDERED\n  notes           String?\n  createdAt       DateTime  @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 8. AI LAB REPORT INTERPRETER (تفسير وترجمة التحاليل الطبية)\n// ----------------------------------------------------\nmodel LabReport {\n  id                    String    @id @default(cuid())\n  customerId            String?\n  customer              Customer? @relation(fields: [customerId], references: [id])\n  imageUrl              String // صورة نتيجة التحليل\n  testType              String    @default(\"CBC\") // CBC, LIPID, LIVER, KIDNEY, HBA1C, GENERAL\n  rawOcrText            String?\n  simplifiedAnalysisAr  String // الشرح الطبي الواضح والمبسط بالعربي للمريض\n  abnormalValues        String // JSON: [{ parameter, value, referenceRange, status: \"HIGH\"|\"LOW\"|\"NORMAL\" }]\n  doctorAdviceQuestions String? // JSON: أسئلة مقترحة يسألها المريض لطبيبه\n  suggestedVitamins     String? // JSON: مكملات وفيتامينات مصرح بها\n  createdAt             DateTime  @default(now())\n}\n\n// ----------------------------------------------------\n// 9. SHORTAGE RADAR MESH (رادار نواقص الأدوية على مستوى الجمهورية)\n// ----------------------------------------------------\nmodel ShortageRequest {\n  id                String    @id @default(cuid())\n  customerId        String?\n  customer          Customer? @relation(fields: [customerId], references: [id])\n  medicineName      String // اسم الدواء الناقص\n  genericName       String? // المادة الفعالة\n  customerCity      String // مدينة العميل\n  governorate       String // محافظة العميل\n  quantityNeeded    Int       @default(1)\n  urgency           String    @default(\"HIGH\") // NORMAL, HIGH, CRITICAL\n  status            String    @default(\"SEARCHING\") // SEARCHING, FOUND, RESERVED, COMPLETED\n  foundPharmacyId   String? // كود الصيدلية التي لبت الطلب\n  reservationExpiry DateTime? // مهلة حجز العلبة للعميل (مثلاً 3 ساعات)\n  notes             String?\n  createdAt         DateTime  @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 10. ORDERS & DELIVERY (إدارة الطلبات والتوصيل)\n// ----------------------------------------------------\nmodel Order {\n  id                String           @id @default(cuid())\n  orderNumber       String           @unique // e.g. DWK-8542\n  pharmacyId        String\n  pharmacy          Pharmacy         @relation(fields: [pharmacyId], references: [id])\n  customerId        String?\n  customer          Customer?        @relation(fields: [customerId], references: [id])\n  customerName      String\n  customerPhone     String\n  customerAddress   String\n  orderType         String           @default(\"DIRECT\") // DIRECT, PRESCRIPTION, SHORTAGE_RADAR, COSMETICS\n  items             String // JSON: [{ medicineId, name, qty, price, total }]\n  subtotal          Float            @default(0)\n  deliveryFee       Float            @default(15)\n  totalAmount       Float            @default(0)\n  paymentMethod     String           @default(\"COD\") // COD, VODAFONE_CASH, INSTAPAY, CARD\n  status            String           @default(\"PENDING\") // PENDING, PREPARING, OUT_FOR_DELIVERY, DELIVERED, CANCELLED\n  courierId         String?\n  courier           Courier?         @relation(fields: [courierId], references: [id])\n  prescriptionId    String?\n  prescription      Prescription?    @relation(fields: [prescriptionId], references: [id])\n  shortageRequestId String?\n  shortageRequest   ShortageRequest? @relation(fields: [shortageRequestId], references: [id])\n  notes             String?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n}\n"
}

